    data_source text DEFAULT 'amap-poi'::text NOT NULL,
    source_url text NOT NULL,
    fetched_at timestamp with time zone NOT NULL,
    verification_status text DEFAULT 'map_record_only'::text NOT NULL,
    lng double precision NOT NULL,
    lat double precision NOT NULL,
    geom public.geometry(Point,4326) NOT NULL,
    geom_gcj02 public.geometry(Point) NOT NULL,
    geom_wgs84 public.geometry(Point,4326) NOT NULL,
    raw jsonb NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT facility_pois_categories_check CHECK ((cardinality(categories) > 0)),
    CONSTRAINT facility_pois_check CHECK ((((lng >= ('-180'::integer)::double precision) AND (lng <= (180)::double precision)) AND ((lat >= ('-90'::integer)::double precision) AND (lat <= (90)::double precision)))),
    CONSTRAINT facility_pois_check1 CHECK ((public.st_equals(geom, geom_wgs84) AND (lng = public.st_x(geom)) AND (lat = public.st_y(geom)))),
    CONSTRAINT facility_pois_data_source_check CHECK ((data_source = 'amap-poi'::text)),
    CONSTRAINT facility_pois_geom_check CHECK ((public.st_isvalid(geom) AND (NOT public.st_isempty(geom)))),
    CONSTRAINT facility_pois_verification_status_check CHECK ((verification_status = 'map_record_only'::text))
);


