--
-- Name: facility_grid_counts; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.facility_grid_counts AS
 WITH assigned AS (
         SELECT p.id,
            p.categories,
            h.id AS hex_id
           FROM (public.facility_pois p
             CROSS JOIN LATERAL ( SELECT g_1.id
                   FROM public.hex_grid g_1
                  WHERE (public.st_covers(g_1.geom, p.geom) OR public.st_dwithin((g_1.geom)::public.geography, (p.geom)::public.geography, (5)::double precision))
                  ORDER BY (public.st_covers(g_1.geom, p.geom)) DESC, (public.st_distance((g_1.geom)::public.geography, (p.geom)::public.geography)), g_1.id
                 LIMIT 1) h)
        )
 SELECT g.id,
    (count(a.id) FILTER (WHERE ('parking'::text = ANY (a.categories))))::integer AS parking_count,
    (count(a.id) FILTER (WHERE (a.categories && ARRAY['office'::text, 'company'::text, 'industrial_park'::text, 'hospital'::text, 'school'::text])))::integer AS office_count,
    (count(a.id) FILTER (WHERE ('work'::text = ANY (a.categories))))::integer AS workplace_count,
    (count(a.id) FILTER (WHERE ('hospital'::text = ANY (a.categories))))::integer AS hospital_count,
    (count(a.id) FILTER (WHERE ('school'::text = ANY (a.categories))))::integer AS school_count,
    (count(a.id) FILTER (WHERE ('leisure'::text = ANY (a.categories))))::integer AS activity_count,
    (count(a.id))::integer AS facility_count,
    (count(a.id) FILTER (WHERE ('commercial'::text = ANY (a.categories))))::integer AS shopping_count,
    (count(a.id) FILTER (WHERE ('leisure'::text = ANY (a.categories))))::integer AS leisure_count,
    (count(a.id) FILTER (WHERE ('public_service'::text = ANY (a.categories))))::integer AS public_service_count
   FROM (public.hex_grid g
     LEFT JOIN assigned a ON ((a.hex_id = g.id)))
  GROUP BY g.id;


